package com.yuegang.zhihui.system.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.system.application.*;import com.yuegang.zhihui.system.security.*;import jakarta.servlet.http.*;import jakarta.validation.*;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/system/dictionaries/admin")public final class SystemDictionaryAdministrationController{private final SystemDictionaryAdministrationService service;private final SystemTrustedUserContextResolver users;public SystemDictionaryAdministrationController(SystemDictionaryAdministrationService s,SystemTrustedUserContextResolver u){service=s;users=u;}@GetMapping ApiResponse<List<DictionaryAdminView>>all(HttpServletRequest r){admin(r);return ok(service.all(),r);}@PutMapping("/{code}")ApiResponse<DictionaryAdminView>type(@PathVariable String code,@Valid @RequestBody SaveDictionaryTypeRequest b,HttpServletRequest r){admin(r);if(!code.equals(b.code()))throw new BusinessException(ErrorCode.VALIDATION_ERROR);return ok(service.saveType(b),r);}@PutMapping("/{code}/items/{key}")ApiResponse<DictionaryAdminView>item(@PathVariable String code,@PathVariable String key,@Valid @RequestBody SaveDictionaryItemRequest b,HttpServletRequest r){admin(r);if(!key.equals(b.key()))throw new BusinessException(ErrorCode.VALIDATION_ERROR);return ok(service.saveItem(code,b),r);}private void admin(HttpServletRequest r){var p=users.resolve(r);if(!p.roles().contains("ADMIN")&&!p.permissions().contains("system:dictionary:write"))throw new BusinessException(ErrorCode.PERMISSION_DENIED);}private static<T>ApiResponse<T>ok(T x,HttpServletRequest r){return ApiResponse.success(x,TraceIdResolver.resolve(r));}}
